<?php
namespace App\Http\Controllers;
use App\Models\SocialPost;use App\Services\ApprovalService;use App\Services\PublishingService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
final class WorkflowController {public function store(Request $r){$d=$r->validate(['idea_id'=>'required|string|max:40','title'=>'required|string|max:180','body'=>'required|string','media_reference'=>'required|string|max:255','channels'=>'required|array|min:1','channels.*'=>'in:instagram,facebook,tiktok,linkedin','scheduled_at'=>'required|date','assigned_person'=>'required|in:A,B']);return response()->json(SocialPost::create($d+['status'=>'draft','version'=>1]),201);}public function edit(Request $r,SocialPost $post){$d=$r->validate(['title'=>'sometimes|required|string|max:180','body'=>'sometimes|required|string','media_reference'=>'sometimes|required|string|max:255','channels'=>'sometimes|required|array|min:1','channels.*'=>'in:instagram,facebook,tiktok,linkedin','scheduled_at'=>'sometimes|required|date']);DB::transaction(function()use($post,$d){$p=SocialPost::query()->lockForUpdate()->findOrFail($post->id);$p->fill($d);$p->version++;$p->status='draft';$p->save();});return response()->json($post->refresh());}public function submit(SocialPost $post,ApprovalService $service){return response()->json($service->submit($post));}public function approve(Request $r,SocialPost $post,ApprovalService $service){$d=$r->validate(['reviewer'=>'required|string|max:100']);return response()->json($service->approve($post,$d['reviewer']));}public function handoff(SocialPost $post,PublishingService $service){return response()->json($service->handoff($post));}}